export const pricing_en = "\n<header class=\"bar\"><a href=\"/\" class=\"logo\"><img src=\"/brand/saymore-wordmark-light.svg\" width=\"103\" alt=\"Saymore\" height=\"28\"></a><nav><a href=\"/api/download\">Download</a><a href=\"/pricing\" aria-current=\"page\">Pricing</a><a href=\"https://github.com/PraxisGrove/Saymore/releases\">Changelog</a><a href=\"https://github.com/PraxisGrove/Saymore\">GitHub</a><a href=\"/zh/pricing\" lang=\"zh-CN\">中文</a></nav></header>\n<main>\n<section class=\"intro\"><h1>Dictation is free.<br>Refinement is a <nobr>one-time</nobr> purchase.</h1><p class=\"lede\">Bring your own API key and dictate as much as you like, for as long as you like. Pay once to unlock refinement and your personal dictionary.</p></section>\n<section class=\"deal\">\n <div class=\"price\">\n  <p class=\"amount\"><span class=\"now\" data-ph>$19</span><span class=\"was\">then <span data-ph>$29</span></span></p>\n  <p class=\"early\">Early price until <span data-ph>Oct 31</span></p>\n  <p class=\"once\">One payment. Twelve months of updates included. After that, the version you have keeps working.</p>\n  <div class=\"cta\"><a class=\"btn primary\" data-checkout href=\"#\">Buy Saymore</a><a class=\"btn\" href=\"https://github.com/PraxisGrove/Saymore/releases/latest\">Download free</a></div>\n  <p class=\"small\">14-day full trial starts when you first open the app. <nobr>No card needed.</nobr></p>\n  <ol class=\"tl\"><li><b>Days 1–14</b><span>Everything unlocked</span></li><li><b>Day 15</b><span>Dictation stays free</span></li><li><b>Months 1–12</b><span>All updates</span></li><li><b>After a year</b><span>Keeps working. Updates $15/yr, optional</span></li></ol>\n </div>\n <aside class=\"key\"><h2>Use your own API key</h2><p>Saymore doesn’t sell transcription credits. You connect a speech provider you already trust, it bills you for what you use, and we add nothing on top.</p><a class=\"link\" href=\"#\">How to get a key</a>\n  \n  <div class=\"providers off\"><div class=\"prov\"><b>OpenAI</b><span class=\"rate off\" data-ph>About $0.18–$0.36 / hour</span><a href=\"https://platform.openai.com/api-keys\">Get an OpenAI key</a></div><div class=\"prov\"><b>Groq</b><a href=\"https://console.groq.com/keys\">Get a Groq key</a></div></div></aside>\n</section>\n<section class=\"compare\"><table><thead><tr><th></th><th scope=\"col\">Free</th><th scope=\"col\">Saymore</th></tr></thead><tbody><tr><th scope=\"row\">Dictation with a global shortcut, typed at your cursor</th><td data-l=\"Free\">Yes</td><td data-l=\"Saymore\">Yes</td></tr><tr><th scope=\"row\">Unlimited dictation with your own key</th><td data-l=\"Free\">Yes</td><td data-l=\"Saymore\">Yes</td></tr><tr><th scope=\"row\">Refinement: removes filler words, fixes punctuation</th><td data-l=\"Free\">During trial</td><td data-l=\"Saymore\">Yes</td></tr><tr><th scope=\"row\">Personal dictionary: CSV import, learns from your edits</th><td data-l=\"Free\">During trial</td><td data-l=\"Saymore\">Yes</td></tr><tr><th scope=\"row\">Devices</th><td data-l=\"Free\">No license needed</td><td data-l=\"Saymore\">3 per license</td></tr></tbody></table></section>\n<section class=\"faq\"><h2>Questions</h2><div class=\"qs\"><div class=\"q\"><h3>Can I get a refund?</h3><p>Yes. Within 14 days of purchase, for any reason. Your license stops working after the refund.</p></div><div class=\"q\"><h3>What happens after the first year?</h3><p>Saymore keeps working, with everything you paid for. You just stop getting new versions. Renew for $15 a year whenever you want them again.</p></div><div class=\"q\"><h3>Which systems are supported?</h3><p>macOS, as one universal app for Intel and Apple Silicon. macOS <span data-ph>13</span> or later, and Windows 10 and 11, 64-bit.</p></div><div class=\"q\"><h3>Do I need a card for the trial?</h3><p>No. Download the app and the 14 days start on first launch.</p></div><div class=\"q\"><h3>How many computers can I use?</h3><p>Three per license. You can move a license by deactivating one of them in the app.</p></div><div class=\"q\"><h3>Is Saymore open source?</h3><p>It is source-available under PolyForm Shield 1.0.0. You can read and build the code; you can’t ship a competing product from it.</p></div></div></section>\n</main><footer>Saymore is source-available under PolyForm Shield 1.0.0. Made by PraxisGrove.</footer>";
